function validate(input) {
  const [{ Triangles = [] }] = input;
  const seen = new Set();
  for (const [a, b, c] of Triangles) {
    if (a === null || b === null || c === null) return 'A, B and C are required.';
    if (a <= 0 || b <= 0 || c <= 0) return 'Side lengths must be positive.';
    const key = `${a},${b},${c}`;
    if (seen.has(key)) return `The triple (${key}) appears twice.`;
    seen.add(key);
  }
  return null;
}

