function generate(rand, size) {
  const pick = n => Math.floor(rand() * n);
  const count = size === 'small' ? pick(9) : 2000;
  const top = size === 'small' ? 8 : 60;
  const seen = new Set(), Triangles = [];
  let attempts = 0;
  while (Triangles.length < count && attempts < count * 20) {
    attempts++;
    const a = 1 + pick(top), b = 1 + pick(top), c = 1 + pick(top);
    const shape = pick(4);
    // Mix equal-sided shapes in on purpose, since random triples rarely repeat a side.
    let row;
    if (shape === 0) row = [a, a, a];
    else if (shape === 1) row = [[a, a, b], [a, b, a], [b, a, a]][pick(3)];
    else if (shape === 2) row = [a, b, a + b - pick(2)].sort(() => rand() - 0.5);
    else row = [a, b, c];
    if (row.some(v => v <= 0)) continue;
    const key = row.join(',');
    if (seen.has(key)) continue;
    seen.add(key);
    Triangles.push(row);
  }
  return [{ Triangles }];
}
